package ospkg

import (
	"context"
	"fmt"
	"sort"

	"golang.org/x/xerrors"

	ospkgDetector "github.com/aquasecurity/trivy/pkg/detector/ospkg"
	"github.com/aquasecurity/trivy/pkg/log"
	"github.com/aquasecurity/trivy/pkg/types"
)

type Scanner interface {
	Scan(ctx context.Context, target types.ScanTarget, options types.ScanOptions) (types.Result, bool, error)
}

type scanner struct {
	opts []ospkgDetector.Option
}

// NewScanner creates a new OS package scanner.
// The given options are forwarded to ospkgDetector.NewDetector during Scan.
func NewScanner(opts ...ospkgDetector.Option) Scanner {
	return &scanner{opts: opts}
}

func (s *scanner) Scan(ctx context.Context, target types.ScanTarget, opts types.ScanOptions) (types.Result, bool, error) {
	if !target.OS.Detected() {
		log.Debug("Detected OS: unknown")
		return types.Result{}, false, nil
	}
	log.Info("Detected OS", log.String("family",
		string(target.OS.Family)), log.String("version", target.OS.Name))

	// Skip OS package scanning if the target is expected not to have OS packages
	if !target.OS.Family.HasOSPackages() {
		log.Debug("Skipping OS package scanning", log.String("family", string(target.OS.Family)))
		return types.Result{}, false, nil
	}

	if target.OS.Extended {
		// TODO: move the logic to each detector
		target.OS.Name += "-ESM"
	}

	result := types.Result{
		Target: fmt.Sprintf("%s (%s %s)", target.Name, target.OS.Family, target.OS.Name),
		Class:  types.ClassOSPkg,
		Type:   target.OS.Family,
	}

	sort.Sort(target.Packages)
	result.Packages = target.Packages

	if !opts.Scanners.Enabled(types.VulnerabilityScanner) {
		// Return packages only
		return result, false, nil
	}

	detector, err := ospkgDetector.NewDetector(target, s.opts...)
	if err != nil {
		return result, false, xerrors.Errorf("unable to initialize Detector for OS packages: %w", err)
	}

	vulns, eosl, err := detector.Detect(ctx)
	if err != nil {
		// Return a result for those who want to override the error handling.
		return result, false, xerrors.Errorf("failed vulnerability detection of OS packages: %w", err)
	}
	result.Vulnerabilities = vulns

	return result, eosl, nil
}

--- ospkg detect ---
// times, the most recently registered supplier is tried first.
func WithSupplier(supplier driver.Supplier) Option {
	return func(r *resolver) {
		r.suppliers = slices.Insert(r.suppliers, 0, supplier)
	}
}

// NewDetector creates a new Detector for the given scan target
func NewDetector(target types.ScanTarget, opts ...Option) (*Detector, error) {
	r := &resolver{
		drivers:   maps.Clone(drivers),
		suppliers: slices.Clone(suppliers),
	}
	for _, opt := range opts {
		opt(r)
	}

	drv, err := r.resolve(target.OS, target.Packages)
	if err != nil {
		return nil, err
	}
	return &Detector{
		target: target,
		driver: drv,
	}, nil
}

// Detect detects the vulnerabilities
func (d *Detector) Detect(ctx context.Context) ([]types.DetectedVulnerability, bool, error) {
	ctx = log.WithContextPrefix(ctx, string(d.target.OS.Family))

	eosl := !d.driver.IsSupportedVersion(ctx, d.target.OS.Family, d.target.OS.Name)

	// gpg-pubkey does not carry a real version.
	// Matching it against any advisory is meaningless, for every driver.
	pkgs := lo.Filter(d.target.Packages, func(pkg ftypes.Package, _ int) bool {
		return pkg.Name != "gpg-pubkey"
	})

	// By default, drop packages installed from third-party repositories such as EPEL or
	// Docker: an OS vendor's advisories do not describe them. A driver whose own feed
	// covers those packages (Echo, Seal, RapidFort) implements PackageFilter to keep them instead.
	filterFunc := driver.DropThirdPartyPackages
	if f, ok := d.driver.(driver.PackageFilter); ok {
		filterFunc = f.FilterPackages
	}

	vulns, err := d.driver.Detect(ctx, d.target.OS.Name, d.target.Repository, filterFunc(ctx, pkgs))
	if err != nil {
		return nil, false, xerrors.Errorf("failed detection: %w", err)
	}

	return vulns, eosl, nil
}

func (r *resolver) resolve(os ftypes.OS, pkgs []ftypes.Package) (driver.Driver, error) {
	// Try suppliers first
	for _, supplier := range r.suppliers {
		if d := supplier(os, pkgs); d != nil {
			return d, nil
		}
	}

	// Fall back to standard drivers
	if d, ok := r.drivers[os.Family]; ok {
		return d, nil
	}

	log.Warn("Unsupported os", log.String("family", string(os.Family)))
	return nil, ErrUnsupportedOS
}

