			require.NoError(t, err)

			a, err := image2.NewArtifact(img, c, tt.artifactOpt)
			require.NoError(t, err)

			got, err := a.Inspect(t.Context())
			if tt.wantErr != "" {
				assert.ErrorContains(t, err, tt.wantErr, tt.name)
				return
			}
			defer a.Clean(got)

			require.NoError(t, err, tt.name)
			assert.Equal(t, tt.want, got)

