	}
	cachedCertificate := cryptotest.CertificateAsset(cryptotest.WithMutate(func(asset *ftypes.CryptoAsset) {
		asset.FilePath = "etc/ssl/certs/ca.pem"
		asset.Certificate.NotAfter = time.Date(2020, 1, 1, 0, 0, 0, 0, time.UTC)
