package types_test

import (
	"encoding/json"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	ftypes "github.com/aquasecurity/trivy/pkg/fanal/types"
	"github.com/aquasecurity/trivy/pkg/types"
)

func TestDetectedVulnerability_LayerJSONCompatibility(t *testing.T) {
	t.Run("report without layer information", func(t *testing.T) {
		input := []byte(`{
			"SchemaVersion": 2,
			"Results": [{
				"Target": "app/composer.lock",
				"Vulnerabilities": [{
					"VulnerabilityID": "CVE-2024-0001",
					"PkgName": "guzzlehttp/guzzle",
					"InstalledVersion": "6.2.0"
				}]
			}]
		}`)

		var report types.Report
		require.NoError(t, json.Unmarshal(input, &report))
		assert.Empty(t, report.Results[0].Vulnerabilities[0].Layer)
	})

	t.Run("report with layer information", func(t *testing.T) {
		report := types.Report{
			SchemaVersion: 2,
			Results: types.Results{
				{
					Target: "app/composer.lock",
					Vulnerabilities: []types.DetectedVulnerability{
						{
							VulnerabilityID: "CVE-2024-0001",
							PkgName:         "guzzlehttp/guzzle",
							Layer: ftypes.Layer{
								Digest: "sha256:layer-digest",
								DiffID: "sha256:layer-diff",
							},
						},
					},
				},
			},
		}

		output, err := json.Marshal(report)
		require.NoError(t, err)
		assert.JSONEq(t, `{
			"SchemaVersion": 2,
			"Results": [{
				"Target": "app/composer.lock",
				"Vulnerabilities": [{
					"VulnerabilityID": "CVE-2024-0001",
					"PkgName": "guzzlehttp/guzzle",
					"Layer": {
						"Digest": "sha256:layer-digest",
						"DiffID": "sha256:layer-diff"
					}
				}]
			}]
		}`, string(output))
	})
}

